#Region CallThisProcess
# A snippet of code provided as an example how to call this process should the developer be working on a system without access to an editor with auto-complete.
If( 1 = 0 );
    ExecuteProcess( '}bedrock.hier.element.delete', 'pLogOutput', pLogOutput,
      'pStrictErrorHandling', pStrictErrorHandling,
    	'pDim', '', 'pHier', '', 'pEle', '',
    	'pDelim', '&'
	);
EndIf;
#EndRegion CallThisProcess

#****Begin: Generated Statements***
#****End: Generated Statements****

################################################################################################### 
##~~Join the bedrock TM1 community on GitHub https://github.com/cubewise-code/bedrock-5 Ver 5.0~~## 
################################################################################################### 

#Region @DOC
# Description:
# This process will delete specified or all elements from a dimension Hierarchy. Elements might be
# specified as a delimited list of elements. Each member in the list might be specified exactly or
# by a wildcard pattern. Wildcards "\*" and "?" are accepted.
#
# Caution: When pEle is set to \*, __all__ elements in pHier will be deleted!
#EndRegion @DOC

##Global Variables
StringGlobalVariable('sProcessReturnCode');
NumericGlobalVariable('nProcessReturnCode');
nProcessReturnCode= 0;

### Constants ###
cThisProcName     = GetProcessName();
cTimeStamp        = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt        = NumberToString( INT( RAND( ) * 100000 ) );
cTemp             = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
cTempDataSource   = cTemp | '_datasource';
cTempSubDim       = cThisProcName |'_dims_'| cTimeStamp |'_'| cRandomInt;
cTempSubHier      = cThisProcName |'_hiers_'| cTimeStamp |'_'| cRandomInt;
cTempSubEle       = cThisProcName |'_eles_'| cTimeStamp |'_'| cRandomInt;
cUserName         = TM1User();
cMsgErrorLevel    = 'ERROR';
cMsgInfoLevel     = 'INFO';
cMsgErrorContent  = 'User:%cUserName% Process:%cThisProcName% ErrorMsg:%sMessage%';
cMsgInfoContent   = 'User:%cUserName% Process:%cThisProcName% Message:%sMessage%';
cLogInfo          = 'Process:%cThisProcName% run with parameters pDim:%pDim%, pHier:%pHier%, pEle:%pEle%, pDelim:%pDelim%.';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pDelim":               "&",
  "pDim":                 null,
  "pEle":                 "*",
  "pHier":                "",
  "pCtrlObj":             0,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0
}';

pPassedParameters = '{
  "pDelim":               '|StringToJson  ( pDelim               )|',
  "pDim":                 '|StringToJson  ( pDim                 )|',
  "pEle":                 '|StringToJson  ( pEle                 )|',
  "pHier":                '|StringToJson  ( pHier                )|',
  "pCtrlObj":             '|NumberToString( pCtrlObj             )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pDelim               =                 JsonToString( JsonGet( pJson, 'pDelim'               ) );
pDim                 =                 JsonToString( JsonGet( pJson, 'pDim'                 ) );
pEle                 =                 JsonToString( JsonGet( pJson, 'pEle'                 ) );
pHier                =                 JsonToString( JsonGet( pJson, 'pHier'                ) );
# Numeric Parameters
pCtrlObj             = StringToNumber( JsonToString( JsonGet( pJson, 'pCtrlObj'             ) ) );
pLogOutput           = StringToNumber( JsonToString( JsonGet( pJson, 'pLogOutput'           ) ) );
pStrictErrorHandling = StringToNumber( JsonToString( JsonGet( pJson, 'pStrictErrorHandling' ) ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
sMessages = JsonAdd( sMessages, '/Info/-', pJson );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0', 0, ' ' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

## LogOutput parameters
IF( pLogoutput = 1 );
    LogOutput('INFO', Expand( cLogInfo ) );   
ENDIF;

### Validate Parameters ###
nErrors = 0;

If( Scan( '*', pDim ) = 0 & Scan( '?', pDim ) = 0 & Scan( pDelim, pDim ) = 0 & Scan( ':', pDim ) > 0 & pHier @= '' );
    # A hierarchy has been passed as dimension. Handle the input error by splitting dim:hier into dimension & hierarchy
    pHier       = SubSt( pDim, Scan( ':', pDim ) + 1, Long( pDim ) );
    pDim        = SubSt( pDim, 1, Scan( ':', pDim ) - 1 );
EndIf;

# Validate Dimension
If( Trim( pDim ) @= '' );
    nErrors = 1;
    sMessage = 'No dimension specified.';
    LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
EndIf;

# If blank delimiter specified then convert to default
If( pDelim @= '' );
    pDelim = '&';
EndIf;

# Validate Hierarchy
If( Trim( pHier ) @= '' );
    ## use same name as Dimension. Since wildcards are allowed this is managed inside the code below
EndIf;

### Check for errors before continuing
If( nErrors <> 0 );
  If( pStrictErrorHandling = 1 ); 
      ProcessQuit; 
  Else;
      ProcessBreak;
  EndIf;
EndIf;

################################################################################################# 
#Region - Create Datasource

# Get Dimensions that match pDim

sDimensionMDX = '';
nCount = JsonSize( pDim );
WHILE( nCount > 0 );
  nCount = nCount - 1;
  sDim = JsonToString( JsonGet( pDim, nCount ) );
  
  sDimensionMDX = sDimensionMDX | ', {TM1FILTERBYPATTERN(TM1SUBSETALL([}Dimensions].[}Dimensions]), "'|sDim|'")}';
END;

# Remove Hierarchies
sDimensionMDX = '{EXCEPT('|DELET( sDimensionMDX, 1, 1 )|', {TM1FILTERBYPATTERN({TM1SUBSETALL([}Dimensions].[}Dimensions])},"*:*")})}';
# Remove Control Objects
IF( pCtrlObj = 0 );
  sDimensionMDX = '{EXCEPT('|sDimensionMDX|', {TM1FILTERBYPATTERN({TM1SUBSETALL([}Dimensions].[}Dimensions])},"}*")})}';
ENDIF;
# Create Dimension Subset
nDimensionCount = SubsetCreatebyMDX( cTemp, sDimensionMDX, '}Dimensions', 1 );


# Get Dimensions/Hierarchies that match pHier
IF( JsonSize( pHier ) > 0 );
  
  sHierarchyMDX = '';
  nCount = JsonSize( pHier );
  WHILE( nCount > 0 );
    nCount = nCount - 1;
    sHier = JsonToString( JsonGet( pHier, nCount ) );
    
    sDimGenerateMDX  = '{TM1FILTERBYPATTERN({[}Dimensions].[}Dimensions].CurrentMember}, "'|sHier|'")}';
    sHierGenerateMDX = '{TM1FILTERBYPATTERN({TM1SUBSETALL([}Dimensions].[}Dimensions])}, [}Dimensions].[}Dimensions].CurrentMember.Name+":'|sHier|'")}';
    sHierMDX = 'GENERATE({TM1SubsetToSet([}Dimensions].[}Dimensions], "'|cTemp|'")}, {'|sDimGenerateMDX|','|sHierGenerateMDX|'})';
    sHierarchyMDX = sHierarchyMDX | ', ' | sHierMDX;
    
  END;
  sHierarchyMDX = '{DISTINCT({' | DELET( sHierarchyMDX, 1, 1 ) | '})}';
  cTemp = cTemp | '_hier';
  SubsetCreatebyMDX( cTemp, sHierarchyMDX, '}Dimensions', 1 );
ENDIF;

# Set Datasource
SubsetMDXSet( '}Dimensions', cTemp, '' );
DataSourceType = 'SUBSET';
DatasourceNameForServer = '}Dimensions';
DatasourceDimensionSubset = cTemp;

#EndRegion - Create Datasource
#################################################################################################

MetadataProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

# Get sDim and sHier from vDimension
nColonIndex = SCAN( ':', vDimension );
IF( nColonIndex <> 0 );
  sDim = SUBST( vDimension, 1, nColonIndex-1 );
  sHier = DELET( vDimension, 1, nColonIndex );
ELSE;
  sDim = vDimension;
  sHier = vDimension;
ENDIF;

# Loop through pEle
sElementMDX = '';
nCount = JsonSize( pEle );
WHILE( nCount > 0 );
  nCount = nCount - 1;
  sEle = JsonToString( JsonGet( pEle, nCount ) );
  
  IF( SCAN( '*', sEle ) <> 0 % SCAN( '?', sEle ) <> 0 );
    sElementMDX = sElementMDX | ', {TM1FILTERBYPATTERN(TM1SUBSETALL(['|sDim|'].['|sHier|']), "'|sEle|'")}';
  ELSE;
    sElementMDX = sElementMDX | ', {['|sDim|'].['|sHier|'].['|sEle|']}';
  ENDIF;
END;
sElementMDX = '{'|DELET( sElementMDX, 1, 1 )|'}';

HierarchySubsetCreate( sDim, sHier, cTemp, 1 );
HierarchySubsetMDXSet( sDim, sHier, cTemp, sElementMDX );
HierarchyDeleteElements( sDim, sHier, cTemp );

EpilogProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

################################################################################################# 
##~~Join the bedrock TM1 community on GitHub https://github.com/cubewise-code/bedrock Ver 4.0~~##
################################################################################################# 

### Return code & final error message handling
If( nErrors > 0 );
    sMessage = 'the process incurred at least 1 error. Please see above lines in this file for more details.';
    nProcessReturnCode = 0;
    LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
    sProcessReturnCode = Expand( '%sProcessReturnCode% Process:%cThisProcName% completed with errors. Check tm1server.log for details.' );
    If( pStrictErrorHandling = 1 ); 
        ProcessQuit; 
    EndIf;
Else;
    sProcessAction      = Expand( 'Process:%cThisProcName% successfully deleted the appropriate elements in hierarchy %pDim%:%pHier%.' );
    sProcessReturnCode = Expand( '%sProcessReturnCode% %sProcessAction%' );
    nProcessReturnCode = 1;
    If( pLogoutput = 1 );
        LogOutput('INFO', Expand( sProcessAction ) );   
    EndIf;
EndIf;
